+ * @returns {{module: object, calls: object, files: object, tracker: object}}
+ */
+function makeActionHarness(overides) {
+    overides = overides || {};
+
+    var files = {}; // file_write captures: path → content
+    var calls = {   // spy registry shared across the host-tool mocks
