+    };
+
+    var scm = {
+        getRemoteRepoInfo: function() {
+            calls.getRemoteRepoInfo++;
+            return def1002(overides.repoInfo, { owner: 'acme', repo: 'widgets' });
+        }
+    };
+
+    var gitOpsStub = {
